package org.retrobridge.galaxyservices.pixel;
import android.app.*;import android.content.*;import android.os.*;
public final class LegacyService extends Service {
 static volatile LegacyService active;
 HotspotLink hotspot;ProxyServer proxy;YouTubeRuntime runtime;MusicRuntime musicRuntime;LocationFeed locations;
 public void onCreate(){super.onCreate();active=this;new Thread(()->{try{IncomingMedia.get(this).initialize();}catch(Exception ignored){}},"incoming-initialize").start();NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("bridge","Galaxy Companion",NotificationManager.IMPORTANCE_LOW));PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);showForeground(new Notification.Builder(this,"bridge").setContentTitle("Galaxy Companion").setContentText("Ready for S2").setSmallIcon(R.drawable.service_notification).setContentIntent(pi).setOngoing(true).build());locations=new LocationFeed(this);runtime=new YouTubeRuntime(this);runtime.start();musicRuntime=new MusicRuntime(this);musicRuntime.start();hotspot=new HotspotLink(this);hotspot.start();new Thread(new Runnable(){public void run(){try{proxy=new ProxyServer(LegacyService.this);proxy.run();}catch(Exception e){try{org.retrobridge.galaxyservices.Wire.writeFile(new java.io.File(getFilesDir(),"status.txt"),("Start: "+e.getClass().getSimpleName()).getBytes("UTF-8"));}catch(Exception ignored){}}}},"proxy-server").start();}
 void showForeground(Notification n){if(Build.VERSION.SDK_INT>=29){int types=android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE;if(checkSelfPermission("android.permission.ACCESS_FINE_LOCATION")==android.content.pm.PackageManager.PERMISSION_GRANTED&&checkSelfPermission("android.permission.ACCESS_BACKGROUND_LOCATION")==android.content.pm.PackageManager.PERMISSION_GRANTED)types|=android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION;startForeground(1,n,types);}else startForeground(1,n);}
 public int onStartCommand(Intent i,int f,int id){return START_STICKY;}
 public IBinder onBind(Intent i){return null;}
 public void onDestroy(){active=null;if(hotspot!=null)hotspot.close();if(proxy!=null)proxy.close();if(runtime!=null)runtime.close();if(musicRuntime!=null)musicRuntime.close();if(locations!=null)locations.close();super.onDestroy();}
}
